head.b:skin:
/* 
===============================================
DARK MODE OVERRIDE (FORCE)
===============================================
*/

/* 全ての標準背景を黒に固定 */
:root {
  --primary-color: #bb86fc;
  --bg-dark: #121212;
  --bg-surface: #1e1e1e;
  --text-main: #e0e0e0;
}

html, body, .page, .page_body, .centered, .centered-bottom, .main, #main {
  background-color: #121212 !important;
  background: #121212 !important;
  color: #e0e0e0 !important;
  background-image: none !important;
}

/* Indieテーマの背景画像・オーバーレイを完全に抹殺 */
.bg-photo, .bg-photo-container, .bg-photo-overlay, .bg-photo-container div {
  display: none !important;
  visibility: hidden !important;
  background: none !important;
  height: 0 !important;
}

/* 記事エリア */
.post-outer-container, .FeaturedPost {
  background-color: #1e1e1e !important;
  border: none !important;
  border-radius: 12px !important;
  padding: 25px !important;
  margin-bottom: 30px !important;
  box-shadow: 0 8px 30px rgba(0,0,0,0.6) !important;
}

/* タイトル回り */
.post-title, .entry-title, .post-title a, h1, h2, h3 {
  font-family: 'Outfit', sans-serif !important;
  color: #ffffff !important;
  text-shadow: none !important;
}

.post-title a { font-size: 2.2rem !important; }

@media screen and (max-width: 640px) {
  .post-title, .entry-title, .post-title a { font-size: 1.5rem !important; }
  .post-outer-container { padding: 15px !important; }
}

/* 人気記事 */
.PopularPosts {
  background-color: #1e1e1e !important;
  padding: 20px !important;
  border-radius: 12px !important;
}
.PopularPosts h3.title { color: #bb86fc !important; border-bottom: 2px solid rgba(187, 134, 252, 0.2); }
.PopularPosts .item-title a { color: #ffffff !important; }

/* サイドバー */
.sidebar-container, .sidebar_top_wrapper, .sidebar_bottom {
  background-color: #121212 !important;
  border-right: 1px solid #333 !important;
}

/* リンク */
a { color: #bb86fc !important; }
.post-footer a, .jump-link a { color: #bb86fc !important; font-weight: bold; }

/* その他テーマ標準CSSの無効化 */
.header-widget { background: none !important; }
